# Liviere/plane fork: remembers the state of every project membership so a periodic task can notice a person
# added to a project again (Plane re-activates the old row without a signal); see
# plane/liviere/unread/queries.py sync_membership_states. Schedules the task every minute.

import django.db.models.deletion
from django.conf import settings
from django.db import migrations, models
from django.utils import timezone


TASK_NAME = "plane.liviere.tasks.sync_unread_memberships"
SCHEDULE_NAME = "liviere: sync memberships for new work items"


def record_current_states(apps, schema_editor):
    ProjectMember = apps.get_model("db", "ProjectMember")
    UnreadMembershipState = apps.get_model("liviere", "UnreadMembershipState")
    now = timezone.now()
    rows = ProjectMember.objects.filter(deleted_at__isnull=True).values_list("member_id", "project_id", "is_active")
    UnreadMembershipState.objects.bulk_create(
        [
            UnreadMembershipState(user_id=user_id, project_id=project_id, is_active=is_active, checked_at=now)
            for user_id, project_id, is_active in rows
        ],
        batch_size=1000,
        ignore_conflicts=True,
    )


def schedule_sync(apps, schema_editor):
    IntervalSchedule = apps.get_model("django_celery_beat", "IntervalSchedule")
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    every_minute, _ = IntervalSchedule.objects.get_or_create(every=1, period="minutes")
    PeriodicTask.objects.update_or_create(
        name=SCHEDULE_NAME,
        defaults={"task": TASK_NAME, "interval": every_minute, "enabled": True},
    )


def unschedule_sync(apps, schema_editor):
    PeriodicTask = apps.get_model("django_celery_beat", "PeriodicTask")
    PeriodicTask.objects.filter(name=SCHEDULE_NAME).delete()


